create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, preferred_language text not null default 'en', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.candidate_profiles (user_id uuid primary key references auth.users(id) on delete cascade, target_roles text[] not null default '{}', skills text[] not null default '{}', experience_level text not null default 'entry' check (experience_level in ('entry','mid','senior')), remote_only boolean not null default true, minimum_salary numeric, salary_currency text, preferred_locations text[] not null default '{}', work_authorization_notes text, confirmed_at timestamptz, updated_at timestamptz not null default now());
create table if not exists public.resumes (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, storage_path text not null, original_filename text not null, mime_type text, size_bytes bigint check (size_bytes is null or size_bytes <= 10485760), parsed_text text, parsed_profile jsonb not null default '{}'::jsonb, parse_status text not null default 'pending' check (parse_status in ('pending','processing','needs_confirmation','confirmed','failed')), created_at timestamptz not null default now(), unique (user_id, storage_path));
create table if not exists public.job_sources (id uuid primary key default gen_random_uuid(), source_key text not null unique, display_name text not null, source_type text not null check (source_type in ('api','feed','company_board','manual')), enabled boolean not null default false, config jsonb not null default '{}'::jsonb, last_checked_at timestamptz, last_error text, created_at timestamptz not null default now());
create table if not exists public.jobs (id uuid primary key default gen_random_uuid(), source_id uuid references public.job_sources(id) on delete set null, external_id text, canonical_url text not null, company_name text not null, title text not null, location_text text, is_remote boolean not null default false, description text not null default '', skills text[] not null default '{}', experience_level text check (experience_level is null or experience_level in ('entry','mid','senior')), published_at timestamptz, expires_at timestamptz, first_seen_at timestamptz not null default now(), last_seen_at timestamptz not null default now(), active boolean not null default true, unique (source_id, external_id));
create table if not exists public.job_matches (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, job_id uuid not null references public.jobs(id) on delete cascade, score integer not null check (score between 0 and 100), reasons jsonb not null default '[]'::jsonb, rejected_reasons jsonb not null default '[]'::jsonb, evaluated_at timestamptz not null default now(), unique (user_id, job_id));
create table if not exists public.applications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, job_id uuid not null references public.jobs(id) on delete cascade, channel text not null check (channel in ('email','official_api','manual')), recipient_email text, subject text, body text, status text not null default 'prepared' check (status in ('prepared','queued','sent','failed','needs_manual_action','replied','interview','rejected','withdrawn')), idempotency_key text not null, provider_message_id text, sent_at timestamptz, error_code text, error_detail text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (user_id, job_id), unique (user_id, idempotency_key));
create table if not exists public.automation_settings (user_id uuid primary key references auth.users(id) on delete cascade, enabled boolean not null default false, daily_application_limit integer not null default 10 check (daily_application_limit between 1 and 30), minimum_match_score integer not null default 80 check (minimum_match_score between 0 and 100), remote_only boolean not null default true, automatic_email_sending boolean not null default false, authorized_api_submission boolean not null default false, automatic_follow_up boolean not null default false, emergency_stop boolean not null default false, updated_at timestamptz not null default now());
create table if not exists public.audit_logs (id bigint generated always as identity primary key, user_id uuid references auth.users(id) on delete set null, event_type text not null, entity_type text, entity_id text, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
alter table public.profiles enable row level security;
alter table public.candidate_profiles enable row level security;
alter table public.resumes enable row level security;
alter table public.job_matches enable row level security;
alter table public.applications enable row level security;
alter table public.automation_settings enable row level security;
alter table public.audit_logs enable row level security;
create policy "Users can read own profile" on public.profiles for select to authenticated using (id = (select auth.uid()));
create policy "Users can insert own profile" on public.profiles for insert to authenticated with check (id = (select auth.uid()));
create policy "Users can update own profile" on public.profiles for update to authenticated using (id = (select auth.uid())) with check (id = (select auth.uid()));
create policy "Users can manage own candidate profile" on public.candidate_profiles for all to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "Users can manage own resumes" on public.resumes for all to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "Users can read own matches" on public.job_matches for select to authenticated using (user_id = (select auth.uid()));
create policy "Users can manage own applications" on public.applications for all to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "Users can manage own automation settings" on public.automation_settings for all to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "Users can read own audit logs" on public.audit_logs for select to authenticated using (user_id = (select auth.uid()));
-- Job-source configuration must be managed by trusted server-side code, not exposed to end users.
